with valid as (select id, product_name, price, cost, stock_qty, tags, supplier_id, floor(stock_qty) stock_qty_whole, coalesce(brand, 'NONE') brand_clean from products where launch_date >= date '2023-04-16' and supplier_id is not null), latest_match as (select s.id, s.product_name, s.price, s.cost, s.supplier_id, s.stock_qty_whole, latest.last_restock, latest.inventory_quantity from valid s left join lateral (select c.last_restock, c.quantity as inventory_quantity from inventory c where c.product_id = s.id order by c.last_restock desc, c.id desc limit 1) latest on true), with_dims as (select src.*, p.rating, p.supplier_name from latest_match src join suppliers p on src.supplier_id <=> p.id), ranked as (select *, row_number() over (partition by supplier_id order by last_restock nulls last, id) as rn from with_dims qualify rn = 1), ranked_products as (select *, row_number() over (partition by supplier_id order by price, id) as latest_rank from ranked qualify latest_rank = 1), enriched as (select id, product_name, price, cost, supplier_id, stock_qty_whole, inventory_quantity, rating, supplier_name, lead(inventory_quantity, 2) over (partition by supplier_id order by stock_qty_whole, id) next_inventory_quantity, sum(rating) over (partition by month(last_restock), supplier_id order by rating, id rows between unbounded preceding and current row) running_rating, lag(rating, 1) over (partition by date_trunc('month', last_restock), supplier_id order by last_restock, id) prev_rating from ranked_products), matched_keys as (select id from enriched except distinct select id from products where price >= 330), kept_rows as (select s.* from enriched s join matched_keys k on s.id = k.id) select s.product_name, s.price, s.cost, s.supplier_id, s.inventory_quantity, s.rating, s.supplier_name, s.next_inventory_quantity, s.running_rating, case when supplier_name rlike '^(Lion City Imports|Global Supply)$' then 'PRIORITY' when supplier_name rlike '^(Siam Parts Co|Tokyo Traders)$' then 'EXTENDED' else 'OTHER_ZONE' end as supplier_name_zone, (select avg(x.cost) from products x where x.supplier_id = s.supplier_id) as avg_product_cost from kept_rows s;
